// Flattened, in viewing order, with ids for linking straight to a page or project.
export const pages = collections.flatMap((collection) =>
  collection.pages.map((page) => ({
    ...page,
    collection,
    projects: page.projects.map((project, index) => ({ ...project, id: `p${page.number}-${index + 1}` })),
  })),
)

