export const projects = pages.flatMap((page) => page.projects.map((project) => ({ ...project, industry: industryByClient[project.client] || 'Business & agriculture', page })))

export const industries = [...new Set(projects.map((p) => p.industry))]
  .map((industry) => ({ industry, count: projects.filter((p) => p.industry === industry).length }))
  .sort((a, b) => b.count - a.count)

export const clientCount = new Set(projects.filter((p) => p.client !== 'Henle Printing').map((p) => p.client)).size

export const tags = [...new Set(projects.flatMap((p) => p.tags))]
  .map((tag) => ({ tag, count: projects.filter((p) => p.tags.includes(tag)).length }))
  .sort((a, b) => b.count - a.count)
